def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    own = []
    opp = []
    opp_D = 0
    for a, b in history:
        own.append(a)
        opp.append(b)
        if b == 'D':
            opp_D += 1

    opp_C = n - opp_D
    last_opp = opp[-1]

    my_D_streak = 0
    for a in reversed(own):
        if a == 'D':
            my_D_streak += 1
        else:
            break

    opp_D_streak = 0
    for a in reversed(opp):
        if a == 'D':
            opp_D_streak += 1
        else:
            break

    opp_C_streak = 0
    for a in reversed(opp):
        if a == 'C':
            opp_C_streak += 1
        else:
            break

    # Most recent round in which we defected and the opponent cooperated.
    # If the opponent keeps defecting afterwards, we were punished and should apologize.
    last_exploit = -1
    for i in range(n - 1, -1, -1):
        if own[i] == 'D' and opp[i] == 'C':
            last_exploit = i
            break

    post_C = 0
    post_D = 0
    if last_exploit >= 0:
        for j in range(last_exploit + 1, n):
            if opp[j] == 'C':
                post_C += 1
            else:
                post_D += 1

    total_after_exploit = n - last_exploit - 1 if last_exploit >= 0 else 0
    contrite = last_exploit >= 0 and post_D == total_after_exploit

    # Recent responsiveness: if after our D the opponent often plays C, they are forgiving/unconditional.
    recentD = 0
    recentC = 0
    start = n - 16
    if start < 0:
        start = 0
    for i in range(start, n - 1):
        if own[i] == 'D':
            recentD += 1
            if opp[i + 1] == 'C':
                recentC += 1

    if recentD > 0:
        forgive = (recentC + 0.5) / (recentD + 1.0)
    else:
        if opp_D == 0:
            forgive = 0.75
        elif opp_C >= opp_D and opp_C >= 4:
            forgive = 0.5
        else:
            forgive = 0.25

    # One observed forgiveness after our exploit plus a short cooperative streak is enough to resume probing.
    if post_C >= 1 and post_D == 0 and opp_C_streak >= 2:
        forgive = 1.0

    high_forgive = forgive > 0.55

    # Count failed deliberate breaks from mutual defection after a long own-D streak.
    break_fail = 0
    for i in range(n - 1):
        if own[i] == 'C' and opp[i] == 'D':
            s = 0
            j = i - 1
            while j >= 0 and own[j] == 'D':
                s += 1
                j -= 1
            if s >= 3:
                if opp[i + 1] == 'D':
                    break_fail += 1

    if last_opp == 'D':
        # Apologize after being punished for an unprovoked defection.
        if contrite and not high_forgive and opp_D_streak < 4:
            return 'C'

        # If stuck in mutual defection and opponent looks retaliatory rather than fully hostile,
        # try one controlled break, but stop after one failed break.
        if (not high_forgive) and my_D_streak >= 3 and break_fail == 0 and opp_D_streak < 12:
            return 'C'

        return 'D'

    # Opponent cooperated last round.
    # Opponent has never defected: exploit a nearly pure cooperator after a short cooperative lock-in.
    if opp_D == 0:
        if n >= 10:
            return 'D'
        return 'C'

    # If the opponent has demonstrated forgiveness/tolerance, exploit their cooperation.
    if high_forgive:
        if opp_C >= opp_D or n >= 80:
            return 'D'

    # If opponent defected earlier but has not ever cooperated on one of our D's yet,
    # test a cooperative streak that follows an opponent defection phase.
    if last_exploit < 0 and opp_D > 0 and opp_C_streak >= 2:
        return 'D'

    return 'C'
